head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getPopupWindow]<br/>지정한 ID 에 해당하는 팝업의 window 객체를 반환합니다.",
    "validation" : [
        "id(필수) 파라미터로 조회하려는 팝업의 ID 를 설정할 수 있어야 합니다.",
        "해당 팝업의 window 객체를 반환해야 합니다.",
        "해당 ID 의 팝업이 없거나 팝업 window 가 null 이면 undefined 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var options = {
        id: "getPopupWindow_1",
        type: "iframePopup",
        width: "600px",
        height: "350px",
        top: "100px",
        left: "100px",
        popupName: "테스트 팝업",
        modal: false
    };

    $p.openPopup("/sample/common_link/util_createPopup_1.xml", options);

    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 완료");
}



scwin.btn_getPopupWindow_onclick = function () {
    var id = par_id.getValue();

    var popWin = $p.getPopupWindow(id);

    if (popWin !== undefined) {
        var result = [];
        result.push("반환 타입 : " + typeof popWin);
        result.push("window 객체 여부 : " + (popWin.document !== undefined ? "PASS" : "FAIL"));
        wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("getPopupWindow('" + id + "') : undefined (팝업 없음)");
    }
}



scwin.btn_closePopup_onclick = function () {
    $p.closePopup("getPopupWindow_1");
    wf_body_bottom.getObj("scwin").setReturnValue("closePopup 실행 완료");
}
